func pipelineStatusStyle(node *TreeNode) lipgloss.Style {
	if node.Type != NodeTypeProject {
		return theme.DimStyle
	}
	switch node.PipelineStatus {
	case "success":
		return theme.StatusOKStyle
	case "failed":
